//! Key presses between frames: a queue so quick typing never drops a key,
//! the modifiers each press was made with, and key repeat timed by the
//! compositor's `wl_keyboard.repeat_info`. Handlers decide which keys act
//! on a repeat (`KeyPress::repeat`) — arrows should, toggles shouldn't.

use std::collections::VecDeque;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug)]
pub struct KeyPress {
    /// evdev keycode.
    pub key: u32,
    pub ctrl: bool,
    pub shift: bool,
    pub logo: bool,
    /// Generated by holding the key down rather than pressing it.
    pub repeat: bool,
}

pub struct Keyboard {
    pub ctrl: bool,
    pub shift: bool,
    pub alt: bool,
    pub logo: bool,
    queue: VecDeque<KeyPress>,
    held: Option<KeyPress>,
    next_repeat: Instant,
    /// Repeats per second; 0 turns repeat off.
    rate: u32,
    delay: Duration,
}

/// Used until the compositor sends `repeat_info` (libinput's defaults).
const DEFAULT_RATE: u32 = 25;
const DEFAULT_DELAY: Duration = Duration::from_millis(600);

impl Keyboard {
    pub fn new() -> Self {
        Self {
            ctrl: false,
            shift: false,
            alt: false,
            logo: false,
            queue: VecDeque::new(),
            held: None,
            next_repeat: Instant::now(),
            rate: DEFAULT_RATE,
            delay: DEFAULT_DELAY,
        }
    }

    pub fn set_repeat_info(&mut self, rate: i32, delay_ms: i32) {
        self.rate = rate.max(0) as u32;
        self.delay = Duration::from_millis(delay_ms.max(0) as u64);
        if self.rate == 0 {
            self.held = None;
        }
    }

    pub fn set_modifiers(&mut self, depressed: u32) {
        self.ctrl = depressed & 4 != 0;
        self.shift = depressed & 1 != 0;
        self.alt = depressed & 8 != 0;
        self.logo = depressed & 64 != 0; // Mod4 = Super/Logo
    }

    pub fn press(&mut self, key: u32, now: Instant) {
        if is_modifier(key) {
            return;
        }
        let press = KeyPress {
            key,
            ctrl: self.ctrl,
            shift: self.shift,
            logo: self.logo,
            repeat: false,
        };
        self.queue.push_back(press);
        // The newest key down is the one that repeats, like everywhere else.
        if self.rate > 0 {
            self.held = Some(KeyPress {
                repeat: true,
                ..press
            });
            self.next_repeat = now + self.delay;
        }
    }

    pub fn release(&mut self, key: u32) {
        if self.held.is_some_and(|h| h.key == key) {
            self.held = None;
        }
    }

    /// Focus left the window: nothing is held any more as far as we know,
    /// and the compositor re-sends modifiers on the next enter.
    pub fn leave(&mut self) {
        self.held = None;
        self.set_modifiers(0);
    }

    pub fn pop(&mut self) -> Option<KeyPress> {
        self.queue.pop_front()
    }

    /// When the held key repeats next, if one is held.
    pub fn repeat_at(&self) -> Option<Instant> {
        self.held.map(|_| self.next_repeat)
    }

    /// Queue the held key's repeat once its deadline has passed.
    pub fn tick_repeat(&mut self, now: Instant) -> bool {
        let Some(held) = self.held else { return false };
        if now < self.next_repeat {
            return false;
        }
        self.queue.push_back(held);
        // Catch up from the deadline (not `now`) so a late wake-up doesn't
        // slow the rate, but never queue a burst after a long stall.
        let interval = Duration::from_secs(1) / self.rate.max(1);
        self.next_repeat = (self.next_repeat + interval).max(now);
        true
    }
}

/// Ctrl, Shift, Alt and Super never act or repeat on their own.
fn is_modifier(key: u32) -> bool {
    matches!(key, 29 | 97 | 42 | 54 | 56 | 100 | 125 | 126)
}

#[cfg(test)]
mod tests {
    use super::*;

    const KEY_RIGHT: u32 = 106;
    const KEY_LEFTCTRL: u32 = 29;

    #[test]
    fn queues_every_press_with_its_modifiers() {
        let mut kb = Keyboard::new();
        let t = Instant::now();
        kb.set_modifiers(4);
        kb.press(KEY_LEFTCTRL, t); // a modifier on its own isn't a press
        kb.press(46, t);
        kb.set_modifiers(0);
        kb.press(47, t);
        let a = kb.pop().unwrap();
        let b = kb.pop().unwrap();
        assert!(kb.pop().is_none());
        assert_eq!((a.key, a.ctrl, a.repeat), (46, true, false));
        assert_eq!((b.key, b.ctrl), (47, false));
    }

    #[test]
    fn held_key_repeats_after_the_delay_at_the_rate() {
        let mut kb = Keyboard::new();
        kb.set_repeat_info(10, 500);
        let t = Instant::now();
        kb.press(KEY_RIGHT, t);
        kb.pop();
        assert!(!kb.tick_repeat(t + Duration::from_millis(499)));
        assert!(kb.tick_repeat(t + Duration::from_millis(500)));
        assert!(kb.pop().is_some_and(|p| p.repeat && p.key == KEY_RIGHT));
        // 10/s: the next one is 100 ms later.
        assert_eq!(kb.repeat_at(), Some(t + Duration::from_millis(600)));
        kb.release(KEY_RIGHT);
        assert_eq!(kb.repeat_at(), None);
        // Rate 0 turns repeat off entirely.
        kb.set_repeat_info(0, 500);
        kb.press(KEY_RIGHT, t);
        assert_eq!(kb.repeat_at(), None);
    }
}
